using System.Data; using System.Globalization; using DocumentFormat.OpenXml; using DocumentFormat.OpenXml.Packaging; using DocumentFormat.OpenXml.Spreadsheet; using SimpleExcel.Internal; using SimpleExcel.Options;
namespace SimpleExcel;
public static class Excel
{
 public const string ContentType="application/vnd.openxmlformats-officedocument.spreadsheetml.sheet";
 public static byte[] Write<T>(IEnumerable<T> data,Action<ExcelWriteOptions<T>>? configure=null){ArgumentNullException.ThrowIfNull(data);var o=new ExcelWriteOptions<T>();configure?.Invoke(o);return Build(ColumnFactory.For(o),data.Cast<object>().ToList(),o);}
 public static byte[] Write(DataTable table,Action<ExcelWriteOptions>? configure=null){ArgumentNullException.ThrowIfNull(table);var o=new ExcelWriteOptions();configure?.Invoke(o);var cols=table.Columns.Cast<DataColumn>().Select((c,i)=>new ExportColumn(c.Caption.Length>0?c.Caption:c.ColumnName,c.DataType,row=>((DataRow)row)[i] is DBNull?null:((DataRow)row)[i],i,i,null)).ToList();return Build(cols,table.Rows.Cast<DataRow>().Cast<object>().ToList(),o);}
 public static void Write<T>(Stream output,IEnumerable<T> data,Action<ExcelWriteOptions<T>>? configure=null){ArgumentNullException.ThrowIfNull(output);var b=Write(data,configure);output.Write(b,0,b.Length);}
 private static byte[] Build(IReadOnlyList<ExportColumn> cols,IReadOnlyList<object> rows,ExcelWriteOptions o)
 {
  using var ms=new MemoryStream();using(var doc=SpreadsheetDocument.Create(ms,SpreadsheetDocumentType.Workbook,true)){var wb=doc.AddWorkbookPart();wb.Workbook=new Workbook();var registry=new StyleRegistry(o);var styleIndexes=cols.Select(c=>registry.GetStyle(c.Format,o.WrapText)).ToArray();var styles=wb.AddNewPart<WorkbookStylesPart>();styles.Stylesheet=registry.Build();styles.Stylesheet.Save();var wp=wb.AddNewPart<WorksheetPart>();var ws=new Worksheet();if(o.FreezeHeader&&o.IncludeHeaders)ws.Append(new SheetViews(new SheetView(new Pane{VerticalSplit=1D,TopLeftCell="A2",ActivePane=PaneValues.BottomLeft,State=PaneStateValues.Frozen}){WorkbookViewId=0U}));if(o.AutoFitColumns&&cols.Count>0)ws.Append(CreateColumns(cols,rows,o));var sd=new SheetData();ws.Append(sd);uint ri=1;if(o.IncludeHeaders){var hr=new Row{RowIndex=ri++};foreach(var c in cols)hr.Append(TextCell(c.Header,1));sd.Append(hr);}foreach(var item in rows){var r=new Row{RowIndex=ri++};for(var i=0;i<cols.Count;i++)r.Append(ValueCell(cols[i].Value(item),styleIndexes[i]));sd.Append(r);}if(o.Header.AutoFilter&&o.IncludeHeaders&&cols.Count>0&&ri>1)ws.Append(new AutoFilter{Reference=$"A1:{ColumnName(cols.Count)}{ri-1}"});wp.Worksheet=ws;wp.Worksheet.Save();wb.Workbook.AppendChild(new Sheets()).Append(new Sheet{Id=wb.GetIdOfPart(wp),SheetId=1,Name=SafeName(o.SheetName)});wb.Workbook.Save();}return ms.ToArray();
 }
 private static Columns CreateColumns(IReadOnlyList<ExportColumn> cols,IReadOnlyList<object> rows,ExcelWriteOptions o){var cs=new Columns();for(var i=0;i<cols.Count;i++){double max=o.IncludeHeaders?cols[i].Header.Length:0;foreach(var row in rows)max=Math.Max(max,Display(cols[i].Value(row)).Length);cs.Append(new Column{Min=(uint)i+1,Max=(uint)i+1,Width=Math.Clamp(max+2,o.ColumnWidth.Minimum,o.ColumnWidth.Maximum),CustomWidth=true});}return cs;}
 private static Cell ValueCell(object? v,uint style)=>v switch{null or DBNull=>new Cell{StyleIndex=style},bool b=>new Cell{CellValue=new CellValue(b?"1":"0"),DataType=CellValues.Boolean,StyleIndex=style},DateTime d=>new Cell{CellValue=new CellValue(d.ToOADate().ToString(CultureInfo.InvariantCulture)),DataType=CellValues.Number,StyleIndex=style},DateTimeOffset d=>new Cell{CellValue=new CellValue(d.DateTime.ToOADate().ToString(CultureInfo.InvariantCulture)),DataType=CellValues.Number,StyleIndex=style},byte or sbyte or short or ushort or int or uint or long or ulong or float or double or decimal=>new Cell{CellValue=new CellValue(Convert.ToString(v,CultureInfo.InvariantCulture)),DataType=CellValues.Number,StyleIndex=style},_=>TextCell(Display(v),style)};
 private static Cell TextCell(string v,uint style)=>new(){InlineString=new InlineString(new Text(v){Space=SpaceProcessingModeValues.Preserve}),DataType=CellValues.InlineString,StyleIndex=style};
 private static string Display(object? v)=>v switch{null or DBNull=>"",DateTime d=>d.ToString("g",CultureInfo.CurrentCulture),DateTimeOffset d=>d.ToString("g",CultureInfo.CurrentCulture),IFormattable f=>f.ToString(null,CultureInfo.CurrentCulture)??"",_=>v.ToString()??""};
 private static string SafeName(string v){var n=string.IsNullOrWhiteSpace(v)?"Datos":v;var bad=new[]{':','\\','/','?','*','[',']'};var s=new string(n.Select(c=>bad.Contains(c)?'_':c).ToArray());return s[..Math.Min(31,s.Length)];}
 private static string ColumnName(int n){var s="";while(n>0){n--;s=(char)('A'+n%26)+s;n/=26;}return s;}
}
